const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const s = lines.join(' ').split(/\s+/).filter(x => x.length)[0];
const n = s.length;
let rank = Array.from(s, (c) => c.charCodeAt(0));
const sa = Array.from({ length: n }, (_, i) => i);
for (let k = 1; ; k *= 2) {
  const r = rank;
  const cmp = (a, b) => (r[a] !== r[b] ? r[a] - r[b] : (a + k < n ? r[a + k] : -1) - (b + k < n ? r[b + k] : -1));
  sa.sort(cmp);
  const nr = new Array(n).fill(0);
  for (let j = 1; j < n; j++) nr[sa[j]] = nr[sa[j - 1]] + (cmp(sa[j - 1], sa[j]) < 0 ? 1 : 0);
  rank = nr;
  if (rank[sa[n - 1]] === n - 1) break;
}
const inv = new Array(n).fill(0);
sa.forEach((p, i) => { inv[p] = i; });
const lcp = new Array(n).fill(0);
let h = 0;
for (let i = 0; i < n; i++) {
  if (inv[i] > 0) {
    const j = sa[inv[i] - 1];
    while (i + h < n && j + h < n && s[i + h] === s[j + h]) h++;
    lcp[inv[i]] = h;
    if (h > 0) h--;
  } else h = 0;
}
console.log(sa.map((p) => p + 1).join(" "));
console.log(String(n * (n + 1) / 2 - lcp.reduce((a, b) => a + b, 0)));

