import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static int[] rank;

    static int second(int i, int k) {
        return i + k < n ? rank[i + k] : -1;
    }

    static int cmp(int a, int b, int k) {
        if (rank[a] != rank[b]) return Integer.compare(rank[a], rank[b]);
        return Integer.compare(second(a, k), second(b, k));
    }

    public static void main(String[] args) throws IOException {
        String s = new BufferedReader(new InputStreamReader(System.in)).readLine().trim();
        n = s.length();
        rank = new int[n];
        for (int i = 0; i < n; i++) rank[i] = s.charAt(i);
        Integer[] sa = new Integer[n];
        for (int i = 0; i < n; i++) sa[i] = i;
        for (int k = 1; ; k *= 2) {
            final int kk = k;
            Arrays.sort(sa, (a, b) -> cmp(a, b, kk));
            int[] nr = new int[n];
            for (int j = 1; j < n; j++) nr[sa[j]] = nr[sa[j - 1]] + (cmp(sa[j - 1], sa[j], kk) < 0 ? 1 : 0);
            rank = nr;
            if (rank[sa[n - 1]] == n - 1) break;
        }
        int[] inv = new int[n];
        for (int i = 0; i < n; i++) inv[sa[i]] = i;
        long sumLcp = 0;
        int h = 0;
        for (int i = 0; i < n; i++) {
            if (inv[i] > 0) {
                int j = sa[inv[i] - 1];
                while (i + h < n && j + h < n && s.charAt(i + h) == s.charAt(j + h)) h++;
                sumLcp += h;
                if (h > 0) h--;
            } else h = 0;
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) out.append(sa[i] + 1).append(i + 1 < n ? " " : "\n");
        out.append((long) n * (n + 1) / 2 - sumLcp).append('\n');
        System.out.print(out);
    }
}

