#include <bits/stdc++.h>
using namespace std;
int main() {
    string s;
    cin >> s;
    int n = s.size();
    vector<int> sa(n), rk(n), tmp(n);
    for (int i = 0; i < n; i++) { sa[i] = i; rk[i] = s[i]; }
    for (int k = 1;; k *= 2) {
        auto second = [&](int i) { return i + k < n ? rk[i + k] : -1; };
        auto cmp = [&](int a, int b) {
            if (rk[a] != rk[b]) return rk[a] < rk[b];
            return second(a) < second(b);
        };
        sort(sa.begin(), sa.end(), cmp);
        tmp[sa[0]] = 0;
        for (int j = 1; j < n; j++) tmp[sa[j]] = tmp[sa[j - 1]] + (cmp(sa[j - 1], sa[j]) ? 1 : 0);
        rk = tmp;
        if (rk[sa[n - 1]] == n - 1) break;
    }
    vector<int> inv(n);
    for (int i = 0; i < n; i++) inv[sa[i]] = i;
    long long sumLcp = 0;
    int h = 0;
    for (int i = 0; i < n; i++) {
        if (inv[i] > 0) {
            int j = sa[inv[i] - 1];
            while (i + h < n && j + h < n && s[i + h] == s[j + h]) h++;
            sumLcp += h;
            if (h > 0) h--;
        } else h = 0;
    }
    for (int i = 0; i < n; i++) printf("%d%c", sa[i] + 1, i + 1 < n ? ' ' : '\n');
    printf("%lld\n", (long long)n * (n + 1) / 2 - sumLcp);
    return 0;
}
